insert into public.frameworks (id, name, short_name, version, description) values
  ('iso27001', 'ISO/IEC 27001:2022', 'ISO 27001', '2022', 'Norme internationale de management de la sécurité de l''information (SMSI). Certifiable par un organisme accrédité.'),
  ('nis2', 'Directive NIS2 (UE 2022/2555)', 'NIS2', '2022/2555', 'Directive européenne de cybersécurité, transposée en France par la loi Résilience. Contrôlée par l''ANSSI.')
