insert into public.controls (id, title, en_clair, theme, priority, applicability_tags, evidence_examples, review_days, sort) values
  ('SMSI.4', 'Contexte et périmètre du SMSI', 'Décrire votre activité, vos parties prenantes (clients, autorités…) et ce que couvre votre démarche de sécurité.', 'gouvernance', 'socle', '{}'::text[], array['Note de contexte et de périmètre', 'Liste des parties intéressées et de leurs attentes']::text[], 365, 0),
  ('SMSI.5', 'Engagement de la direction et politique', 'La direction porte la démarche, approuve la politique et les moyens, et en rend compte.', 'gouvernance', 'socle', '{}'::text[], array['Politique signée par la direction', 'Décision de lancement de la démarche']::text[], 365, 1),
  ('SMSI.5.3', 'Rôles et responsabilités du SMSI', 'Nommer un responsable de la démarche et préciser qui rend compte à la direction.', 'gouvernance', 'socle', '{}'::text[], array['Lettre de nomination du responsable sécurité', 'Organigramme du SMSI']::text[], 365, 2),
  ('SMSI.6.1', 'Appréciation et traitement des risques', 'Lister ce qui pourrait mal tourner, évaluer la gravité et la probabilité, et décider quoi faire pour chaque risque.', 'gouvernance', 'socle', '{}'::text[], array['Registre des risques', 'Plan de traitement des risques validé']::text[], 365, 3),
  ('SMSI.SOA', 'Déclaration d''applicabilité', 'Le document qui liste toutes les mesures de l''annexe A, dit lesquelles vous appliquez et justifie les exclusions. Il est généré automatiquement par l''outil.', 'gouvernance', 'socle', '{}'::text[], array['Déclaration d''applicabilité exportée et signée']::text[], 365, 4),
  ('SMSI.6.2', 'Objectifs de sécurité', 'Fixer quelques objectifs mesurables (ex. 100 % des postes à jour) et planifier les changements.', 'gouvernance', 'standard', '{}'::text[], array['Tableau des objectifs avec indicateurs', 'Plan d''action daté']::text[], 365, 5),
  ('SMSI.7', 'Ressources, compétences et communication', 'Vérifier que les personnes impliquées ont le temps et les compétences, et organiser la communication sur la sécurité.', 'gouvernance', 'standard', '{}'::text[], array['Matrice de compétences', 'Plan de communication interne']::text[], 365, 6),
  ('SMSI.7.3', 'Sensibilisation au SMSI', 'Chacun connaît la politique de sécurité et sait ce qu''on attend de lui.', 'gouvernance', 'standard', '{}'::text[], array['Attestations de lecture de la politique']::text[], 365, 7),
  ('SMSI.7.5', 'Documentation et maîtrise opérationnelle', 'Tenir à jour les documents de la démarche (versions, validations) et appliquer ce qui est prévu.', 'gouvernance', 'standard', '{}'::text[], array['Liste des documents avec version et date', 'Historique des validations']::text[], 365, 8),
  ('SMSI.9.1', 'Indicateurs et suivi', 'Suivre quelques indicateurs (score de conformité, incidents, formations) pour mesurer les progrès.', 'gouvernance', 'standard', '{}'::text[], array['Tableau de bord des indicateurs (export de l''outil)']::text[], 180, 9),
  ('SMSI.9.2', 'Audit interne', 'Vérifier au moins une fois par an que la démarche fonctionne, avant l''auditeur externe.', 'gouvernance', 'standard', '{}'::text[], array['Programme d''audit interne', 'Rapport d''audit interne']::text[], 365, 10),
  ('SMSI.9.3', 'Revue de direction', 'Une réunion annuelle où la direction fait le point et prend des décisions sur la sécurité.', 'gouvernance', 'standard', '{}'::text[], array['Compte rendu de revue de direction signé']::text[], 365, 11),
  ('SMSI.10', 'Amélioration et actions correctives', 'Traiter les écarts constatés, corriger leurs causes et suivre les actions jusqu''au bout.', 'gouvernance', 'standard', '{}'::text[], array['Registre des non-conformités et actions correctives']::text[], 180, 12),
  ('NIS2.20', 'Formation des dirigeants à la cybersécurité', 'Les dirigeants suivent une formation pour comprendre les risques cyber et les décisions qu''ils doivent prendre.', 'gouvernance', 'socle', array['nis2']::text[], array['Attestation de formation des dirigeants']::text[], 365, 13),
  ('NIS2.23', 'Notification des incidents à l''ANSSI', 'Savoir notifier un incident important : alerte sous 24 h, notification sous 72 h, rapport final sous 1 mois.', 'gouvernance', 'socle', array['nis2']::text[], array['Procédure de notification', 'Test ou exercice de notification réalisé']::text[], 365, 14),
  ('NIS2.27', 'Enregistrement auprès de l''ANSSI', 'S''enregistrer sur MonEspaceNIS2 et tenir les informations à jour.', 'gouvernance', 'socle', array['nis2']::text[], array['Capture de l''enregistrement sur MonEspaceNIS2']::text[], 365, 15),
  ('A.5.1', 'Politiques de sécurité de l''information', 'Écrire une politique de sécurité courte, validée et signée par la direction, et la communiquer à tous.', 'organisationnel', 'socle', '{}'::text[], array['Politique de sécurité signée par le dirigeant', 'Preuve de diffusion (email, affichage, accusé de lecture)']::text[], 365, 16),
  ('A.5.2', 'Rôles et responsabilités en sécurité', 'Désigner qui s''occupe de quoi en sécurité (référent interne, prestataire informatique, dirigeant).', 'organisationnel', 'socle', '{}'::text[], array['Organigramme sécurité ou fiche de poste du référent', 'Contrat du prestataire informatique précisant son rôle']::text[], 365, 17),
  ('A.5.3', 'Séparation des tâches', 'Éviter qu''une même personne puisse à la fois demander, valider et exécuter une action sensible (ex. paiement, droits d''accès).', 'organisationnel', 'standard', array['salaries']::text[], array['Matrice des validations (qui demande / qui valide)', 'Extrait de paramétrage des droits dans les outils']::text[], 365, 18),
  ('A.5.4', 'Responsabilités de la direction', 'La direction s''assure que chacun applique les règles de sécurité et y consacre les moyens nécessaires.', 'organisationnel', 'standard', '{}'::text[], array['Compte rendu de réunion de direction mentionnant la sécurité', 'Budget ou plan d''action validé']::text[], 365, 19),
  ('A.5.5', 'Relations avec les autorités', 'Savoir qui contacter en cas d''incident : ANSSI/CERT-FR, CNIL, police/gendarmerie, cybermalveillance.gouv.fr.', 'organisationnel', 'standard', '{}'::text[], array['Fiche des contacts d''urgence à jour', 'Procédure indiquant quand contacter chaque autorité']::text[], 365, 20),
  ('A.5.6', 'Relations avec des groupes spécialisés', 'Suivre au moins une source spécialisée (CERT-FR, CLUSIF, fédération professionnelle) pour rester informé.', 'organisationnel', 'standard', '{}'::text[], array['Abonnement à une lettre d''alerte (capture)', 'Participation à un club ou groupe métier']::text[], 365, 21),
  ('A.5.7', 'Veille sur les menaces', 'Surveiller les menaces qui concernent votre activité (alertes CERT-FR, fournisseurs) et en tenir compte.', 'organisationnel', 'standard', '{}'::text[], array['Journal des alertes reçues et des suites données', 'Abonnement aux bulletins de sécurité des éditeurs utilisés']::text[], 365, 22),
  ('A.5.8', 'Sécurité dans la gestion de projet', 'Intégrer une question sécurité dans chaque nouveau projet (nouvel outil, nouveau site, nouvelle machine connectée).', 'organisationnel', 'standard', '{}'::text[], array['Check-list sécurité projet remplie', 'Compte rendu de lancement de projet']::text[], 365, 23),
  ('A.5.9', 'Inventaire des informations et des actifs', 'Tenir une liste à jour de vos équipements, logiciels et données importantes, avec un responsable pour chacun.', 'organisationnel', 'socle', '{}'::text[], array['Inventaire des actifs (tableur ou export outil)', 'Date de dernière mise à jour de l''inventaire']::text[], 365, 24),
  ('A.5.10', 'Utilisation acceptable des actifs', 'Fixer les règles d''usage des outils (ordinateurs, messagerie, Internet) dans une charte connue de tous.', 'organisationnel', 'standard', '{}'::text[], array['Charte informatique signée', 'Annexe au règlement intérieur']::text[], 365, 25),
  ('A.5.11', 'Restitution des actifs', 'Récupérer le matériel, les badges et les clés quand quelqu''un quitte l''entreprise.', 'organisationnel', 'standard', array['salaries']::text[], array['Check-list de départ signée', 'Registre de remise du matériel']::text[], 365, 26),
  ('A.5.12', 'Classification des informations', 'Classer les informations selon leur sensibilité (publique, interne, confidentielle).', 'organisationnel', 'standard', '{}'::text[], array['Règle de classification documentée', 'Exemples de documents classés']::text[], 365, 27),
  ('A.5.13', 'Marquage des informations', 'Indiquer visiblement la sensibilité d''un document (mention « Confidentiel », dossier dédié…).', 'organisationnel', 'standard', '{}'::text[], array['Modèle de document avec mention de classification', 'Photo d''un classeur étiqueté']::text[], 365, 28),
